#include "stdlib/lapack/base/dla_porpvgrw.h"
#include "stdlib/constants/float64/nan.h"

/**
* Computes reciprocal Cholesky pivot growth using a matrix storage layout.
*
* @param layout    storage layout
* @param uplo      stored triangle
* @param NCOLS     leading square order
* @param A         original matrix
* @param LDA       leading dimension of A
* @param AF        supplied Cholesky factor
* @param LDAF      leading dimension of AF
* @param WORK      scratch storage with 2*NCOLS entries
* @return          reciprocal pivot growth or NaN for invalid options
*/
double API_SUFFIX(c_dla_porpvgrw)( const LAPACK_LAYOUT layout, const LAPACK_UPLO uplo, const LAPACK_INT NCOLS, const double *A, const LAPACK_INT LDA, const double *AF, const LAPACK_INT LDAF, double *WORK ) {
	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( NCOLS > 0 && (LDA < NCOLS || LDAF < NCOLS) ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( layout == LAPACK_COL_MAJOR ) {
		return API_SUFFIX(c_dla_porpvgrw_ndarray)( uplo, NCOLS, A, 1, LDA, 0, AF, 1, LDAF, 0, WORK, 1, 0 );
	}
	return API_SUFFIX(c_dla_porpvgrw_ndarray)( uplo, NCOLS, A, LDA, 1, 0, AF, LDAF, 1, 0, WORK, 1, 0 );
}
